using TheTechIdea.Data.OilGas;
using Beep.OilandGas.Models.Data.ProductionAccounting;
namespace Beep.OilandGas.Web.Services;
public sealed partial class AccountingServiceClient
{
    private const string FxRoute="api/accounting/traditional/gl/company-accounts/fx-rates";
    private static string FxQuery(string book,string currency,DateTime date){CompanyGLMappingReview.RequireDate(date);return "?book="+Uri.EscapeDataString(book)+"&sourceCurrency="+Uri.EscapeDataString(currency)+"&date="+date.ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture);}
    public async Task<CompanyFxRateReview> GetCompanyFxRatesAsync(string book,string sourceCurrency,DateTime date){var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original company/account.");var result=await _apiClient.GetAsync<CompanyFxRateReview>(FxRoute+FxQuery(book,sourceCurrency,date)) ??throw new InvalidOperationException("The complete original company FX source is unavailable.");if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during FX review.");result.Require(snapshot.Selection.Scope,snapshot.Selection.UserId,book,sourceCurrency,date);result.RequireWindow(date,date);return CompanyInventorySourceReview.Copy(result);}
    public Task<CompanyFxRateConfigurationReview> GetCompanyFxRateConfigurationReviewAsync(string book,string sourceCurrency,DateTime date)=>GetCompanyFxRateConfigurationReviewAsync(book,sourceCurrency,date,date);
    public async Task<CompanyFxRateConfigurationReview> GetCompanyFxRateConfigurationReviewAsync(string book,string sourceCurrency,DateTime from,DateTime through){CompanyGLMappingReview.RequireDate(through);var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original company/account.");var result=await _apiClient.GetAsync<CompanyFxRateConfigurationReview>(FxRoute+"/configuration-review"+FxQuery(book,sourceCurrency,from)+"&through="+through.ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture)) ??throw new InvalidOperationException("The original FX management source is unavailable.");if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during FX management review.");result.Require(snapshot.Selection.Scope,snapshot.Selection.UserId,book,sourceCurrency,from);result.Source.RequireWindow(from,through);return CompanyInventorySourceReview.Copy(result);}
    public async Task<FX_RATE> ConfigureCompanyFxRateAsync(CompanyFxRateConfigurationSubmission submission){submission=CompanyInventorySourceReview.Copy(submission);submission.Command.Require();var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null || snapshot.Selection.Scope!=submission.Command.Company || snapshot.Selection.UserId!=submission.Command.ActorUserId)throw new InvalidOperationException("Return to the original rate company/account.");var row=await _apiClient.PostAsync<CompanyFxRateConfigurationSubmission,FX_RATE>(FxRoute+"/configuration",submission) ??throw new InvalidOperationException("The original rate outcome is unconfirmed.");if(snapshot!=_apiClient.CompanySnapshot || CompanyFxRateProof.Require(row).Command!=submission.Command)throw new InvalidOperationException("The exact original rate/company context is unconfirmed.");return CompanyInventorySourceReview.Copy(row);}
    public async Task<FX_RATE?> GetCompanyFxRateConfigurationAsync(string id){if(!Guid.TryParseExact(id,"N",out var identity) || identity==Guid.Empty || identity.ToString("N")!=id)throw new ArgumentException("The original native FX identity is required.");var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original rate producer company/account.");var row=await _apiClient.GetAsync<FX_RATE>(FxRoute+"/configuration/"+Uri.EscapeDataString(id));if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during rate recovery.");if(row is null)return null;var command=CompanyFxRateProof.Require(row).Command;if(command.Company!=snapshot.Selection.Scope || command.ActorUserId!=snapshot.Selection.UserId || command.Id!=id)throw new InvalidOperationException("The private rate belongs to another context.");return CompanyInventorySourceReview.Copy(row);}
}
